const VIEW_BOXES = {
  "chevron-down": "2.525 2.7 8.6 8.6",
  "chevron-right": "2.525 2.7 8.6 8.6",
};

export const ICON_NAMES = Object.keys(ICONS);

export function Icon({ name, size = 14, className }) {
  const glyph = ICONS[name] ?? ICONS.puzzle;
  return (
    <svg className={className} width={size} height={size} viewBox={VIEW_BOXES[name] ?? "0 0 14 14"} fill="currentColor" aria-hidden="true">
      {glyph}
    </svg>
  );
}
